import{_ as i,C as a,c as l,o as c,a3 as n,G as o,j as e,a as r}from"./chunks/framework.Dokpd4od.js";const w=JSON.parse('{"title":"Sell in other currencies","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/sales/products-prices/sell-in-other-currencies.md","filePath":"master/sales/sales/products-prices/sell-in-other-currencies.md","lastUpdated":1791902625000}'),u={name:"master/sales/sales/products-prices/sell-in-other-currencies.md"};function h(d,t,p,g,m,y){const s=a("ImagePopup");return c(),l("div",null,[t[3]||(t[3]=n('<h1 id="sell-in-other-currencies" tabindex="-1">Sell in other currencies <a class="header-anchor" href="#sell-in-other-currencies" aria-label="Permalink to &quot;Sell in other currencies&quot;">​</a></h1><p>Your products keep their price in one currency, your <strong>base currency</strong>, for example USD. When a customer wants a quotation in another currency, such as Indian rupees, you do not have to retype any price. Aureus converts the prices for you, using an exchange rate that you keep, and shows the quotation and its totals in the new currency.</p><blockquote><p><strong>In simple words:</strong> Pick a price list that is set to the customer&#39;s currency. Aureus changes every price on the quotation to that currency.</p></blockquote><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need&quot;">​</a></h2><p>To sell in another currency, you set up three things once:</p><ol><li>The <strong>Price Lists</strong> feature is on.</li><li>The other currency is <strong>active</strong> and has an <strong>exchange rate</strong>.</li><li>A <strong>price list</strong> uses that currency.</li></ol><p>Then you choose the price list on each quotation. The steps below show each part with an example: the <strong>Camping Hammock</strong> costs <strong>65</strong> in USD, and you want to quote it in <strong>INR</strong>.</p><h2 id="step-1-turn-on-price-lists" tabindex="-1">Step 1: Turn on price lists <a class="header-anchor" href="#step-1-turn-on-price-lists" aria-label="Permalink to &quot;Step 1: Turn on price lists&quot;">​</a></h2><ol><li>Go to <code>Sales → Settings → Manage Products</code>.</li><li>Turn on <strong>Price Lists</strong> (Allow products to be sold at prices set by a price list).</li><li>Click <strong>Save changes</strong>.</li></ol>',9)),o(s,{src:"/images1/sales/set_products.png",alt:"Manage Products settings with Variants, Unit of Measure, Packagings and Price Lists"}),t[4]||(t[4]=n('<p>Until you do this, the <strong>Price List</strong> field does not show on a quotation.</p><h2 id="step-2-make-the-currency-active-and-add-a-rate" tabindex="-1">Step 2: Make the currency active and add a rate <a class="header-anchor" href="#step-2-make-the-currency-active-and-add-a-rate" aria-label="Permalink to &quot;Step 2: Make the currency active and add a rate&quot;">​</a></h2><p>Only active currencies can be used on a price list. Most currencies come with the system but are switched off.</p><ol><li><p>Go to <code>Sales → Configurations → Currencies</code>.</p></li><li><p>Open the <strong>Inactive</strong> tab, find the currency, for example <strong>INR</strong>, and click <strong>Edit</strong>.</p></li><li><p>In <strong>Status &amp; Configuration</strong>, turn on <strong>Status</strong>.</p></li><li><p>In <strong>Currency Rates</strong>, click <strong>Add Rate</strong> and fill in the row:</p><ul><li><strong><em>Date:</em></strong> The day the rate starts. It is today by default.</li><li><strong><em>Unit Per USD:</em></strong> How many units of this currency one unit of your base currency buys. For example <code>83</code> means 1 USD = 83 INR.</li><li><strong><em>USD Per Unit:</em></strong> Filled in for you. It is the other way round (about 0.012 USD for 1 INR).</li></ul></li><li><p>Click <strong>Save changes</strong>.</p></li></ol>',4)),o(s,{src:"/images1/sales/currency_inr_rate.png",alt:"Edit INR currency with Status turned on and one rate row of 83 Unit Per USD"}),t[5]||(t[5]=e("p",null,[r("The currency now shows on the "),e("strong",null,"Active"),r(" tab of the list.")],-1)),o(s,{src:"/images1/sales/cfg_currencies.png",alt:"Currencies list on the Active tab with USD and INR"}),t[6]||(t[6]=n('<div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Exchange rates change. When the rate changes, add a <strong>new row</strong> with a new date. Do not edit the old row. Aureus always uses the row with the latest date that is not later than today, and the older rows stay as a history.</p></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>The rate must be <strong>1 or more</strong>. The form does not accept a smaller number. Keep this in mind for currencies that are worth more than your base currency.</p></div><p>For more about the base currency and the other currency fields, see <a href="./../../../general-settings/companies/currency.html">Currency</a>.</p><h2 id="step-3-create-a-price-list-in-that-currency" tabindex="-1">Step 3: Create a price list in that currency <a class="header-anchor" href="#step-3-create-a-price-list-in-that-currency" aria-label="Permalink to &quot;Step 3: Create a price list in that currency&quot;">​</a></h2><ol><li>Go to <code>Sales → Products → Price Lists</code> and click <strong>New Price List</strong>.</li><li>Enter a <strong>Price List Name</strong>, for example <code>India Price List (INR)</code>.</li><li>Choose the <strong>Currency</strong>, for example INR.</li><li>Click <strong>Create</strong>.</li></ol>',5)),o(s,{src:"/images1/sales/pricelist_inr_form.png",alt:"Create Price List form with the name India Price List (INR) and currency INR"}),t[7]||(t[7]=e("p",null,[r("You do not need to add rules. A price list with no rules still converts every product price. Add rules only when you want a different price for some products. See "),e("a",{href:"./price-lists.html"},"Price lists"),r(".")],-1)),o(s,{src:"/images1/sales/pricelists.png",alt:"Price Lists list with India Price List (INR)"}),t[8]||(t[8]=e("h2",{id:"step-4-use-the-price-list-on-a-quotation",tabindex:"-1"},[r("Step 4: Use the price list on a quotation "),e("a",{class:"header-anchor",href:"#step-4-use-the-price-list-on-a-quotation","aria-label":'Permalink to "Step 4: Use the price list on a quotation"'},"​")],-1)),e("ol",null,[t[1]||(t[1]=e("li",null,[e("p",null,[r("Create a quotation and choose the customer. See "),e("a",{href:"./../quotations-orders/create-quotation.html"},"Create a quotation"),r(".")])],-1)),e("li",null,[t[0]||(t[0]=e("p",null,[r("Add the products. At this point the lines are in your base currency. Here the Camping Hammock has a "),e("strong",null,"Unit Price"),r(" of "),e("code",null,"65"),r(", and 5 units give an "),e("strong",null,"Amount"),r(" of "),e("code",null,"325"),r(".")],-1)),o(s,{src:"/images1/sales/pricelist_convert_usd.png",alt:"Quotation with Camping Hammock, quantity 5, unit price 65 in USD"})]),t[2]||(t[2]=e("li",null,[e("p",null,[r("In "),e("strong",null,"Price List"),r(", choose "),e("strong",null,"India Price List (INR)"),r(".")])],-1))]),t[9]||(t[9]=e("p",null,[r("The quotation changes to rupees at once. Every line is priced again, and the totals are in the new currency. The Camping Hammock now has a "),e("strong",null,"Unit Price"),r(" of "),e("code",null,"5395"),r(" (65 x 83), and 5 units give "),e("code",null,"26975"),r(".")],-1)),o(s,{src:"/images1/sales/pricelist_convert_inr.png",alt:"The same quotation with the INR price list: unit price 5395 and total 26,975 rupees"}),t[10]||(t[10]=n('<p>You do not choose the currency anywhere else. The quotation takes the currency of the price list. If you change the price list later, Aureus prices the lines again.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>When you choose a customer who already has a price list saved, Aureus fills in that price list for you.</p></div><h2 id="how-the-price-on-each-line-is-decided" tabindex="-1">How the price on each line is decided <a class="header-anchor" href="#how-the-price-on-each-line-is-decided" aria-label="Permalink to &quot;How the price on each line is decided&quot;">​</a></h2><p>For every product line, Aureus first looks at the rules of the price list.</p><ul><li><strong>A rule matches the product.</strong> The rule decides the price. <ul><li><strong>Fixed Price:</strong> The amount you typed in the rule is used as it is. Type it in the currency of the price list. The exchange rate is not used.</li><li><strong>Discount</strong> or <strong>Formula:</strong> The discount or formula is applied to the sales price, or the cost, or another price list, after that price is converted to the currency of the list.</li></ul></li><li><strong>No rule matches.</strong> Aureus converts the normal sales price of the product with the exchange rate.</li></ul><p><strong>Example:</strong> you add a <strong>Fixed Price</strong> rule of <code>5000</code> for the Camping Hammock in the INR price list. The line then shows <code>5000</code> and not <code>5395</code>.</p><h2 id="check-that-it-works" tabindex="-1">Check that it works <a class="header-anchor" href="#check-that-it-works" aria-label="Permalink to &quot;Check that it works&quot;">​</a></h2><p>If the prices do not change after you choose the price list, check these points:</p><ul><li>The currency has at least one rate row. If a currency has <strong>no rate</strong>, Aureus treats the rate as 1. Then 65 USD shows as 65 INR, with no conversion.</li><li>The rate row has a date that is today or earlier.</li><li>The currency is <strong>active</strong>.</li><li>You chose the price list on the quotation, and the <strong>Price Lists</strong> setting is on.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./price-lists.html">Price lists</a></li><li><a href="./../../../general-settings/companies/currency.html">Currency</a></li><li><a href="./../quotations-orders/create-quotation.html">Create a quotation</a></li><li><a href="./discounts-margins.html">Discounts and margins</a></li></ul>',11))])}const T=i(u,[["render",h]]);export{w as __pageData,T as default};
